text:
& .in-app-notification-description {
  color: var(--text);
  font-size: 0.9rem;
  min-block-size: 2lh;
  margin: 0;
  hyphens: auto;
  max-block-size: 20lh;
  overflow: auto;
}

& .icon {
  position: absolute;
  z-index: 9;
  pointer-events: none;
  content: var(--icon-url);
  -moz-context-properties: fill, stroke;
  fill: var(--icon-fill);
  stroke: var(--icon-stroke);

  &:dir(rtl) {
    transform: scaleX(-1);
  }
